package com.credvenn.lm.applicationvariable;
import com.credvenn.lm.common.domain.AuditableEntity;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="application_variable_definitions") public class ApplicationVariableDefinition extends AuditableEntity{@Id @Column(length=36)String id;@Column(name="tenant_id",nullable=false)String tenantId;@Column(nullable=false)String code;@Column(nullable=false)String label;@Column(name="section_name")String sectionName;@Enumerated(EnumType.STRING)@Column(name="field_type",nullable=false)ApplicationVariableFieldType fieldType;@Column(nullable=false)boolean required;@Column(nullable=false)boolean active=true;@Column(name="display_order")int displayOrder;@Column(name="options_json",columnDefinition="TEXT")String optionsJson;@PrePersist void id(){if(id==null)id=UUID.randomUUID().toString();}}
